code='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            objects.append((color, cells))

    def has_hole(cells):
        top = min(y for y, x in cells)
        bottom = max(y for y, x in cells)
        left = min(x for y, x in cells)
        right = max(x for y, x in cells)
        occupied = set(cells)
        exterior = set()
        q = deque()
        for y in range(top, bottom + 1):
            for x in range(left, right + 1):
                if (y in (top, bottom) or x in (left, right)) and (y, x) not in occupied:
                    exterior.add((y, x))
                    q.append((y, x))
        while q:
            y, x = q.popleft()
            for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                if top <= ny <= bottom and left <= nx <= right and (ny,nx) not in occupied and (ny,nx) not in exterior:
                    exterior.add((ny,nx))
                    q.append((ny,nx))
        return any((y, x) not in occupied and (y, x) not in exterior
                   for y in range(top, bottom + 1) for x in range(left, right + 1))

    holes = [(color, cells) for color, cells in objects if has_hole(cells)]
    solids = [(color, cells) for color, cells in objects if not has_hole(cells)]
    holes.sort(key=lambda item: min(y for y, x in item[1]))
    solids.sort(key=lambda item: -max(y for y, x in item[1]))
    placed = [[0] * w for _ in range(h)]
    for upward, group in [(True, holes), (False, solids)]:
        for color, cells in group:
            dy = -1 if upward else 1
            while True:
                moved = [(y + dy, x) for y, x in cells]
                if any(y < 0 or y >= h or placed[y][x] != 0 for y, x in moved):
                    break
                cells = moved
            for y, x in cells:
                placed[y][x] = color
    return placed
'''
